import {localizeDocument} from './site-language.js';
import {getLanguage} from './i18n.mjs';
const $=s=>document.querySelector(s);
const date=s=>new Intl.DateTimeFormat(getLanguage()==='en'?'en-US':'tr-TR',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'));
const size=n=>(n/1000000).toLocaleString(getLanguage()==='en'?'en-US':'tr-TR',{maximumFractionDigits:2})+' MB';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rows=[],limit=18,lastFocus=null,catalogDate='';
document.addEventListener('atlas-language-change',()=>{if(!rows.length)return;$('#latest-date').textContent=date(rows[0].date);$('#catalog-date').textContent=(getLanguage()==='en'?'Catalog: ':'Katalog: ')+date(catalogDate);render()});
function reset(){for(const id of ['search','sector','market','type','from','to'])$('#'+id).value='';$('#sort').value='new';limit=18;render()}
function filtered(){const q=$('#search').value.trim().toLocaleLowerCase('tr-TR'),latin=$('#search').value.trim().toLowerCase();return rows.filter(r=>(!q||`${r.company} ${r.ticker}`.toLocaleLowerCase('tr-TR').includes(q)||`${r.company} ${r.ticker}`.toLowerCase().includes(latin))&&(!$('#sector').value||r.sector===$('#sector').value)&&(!$('#market').value||r.market===$('#market').value)&&(!$('#type').value||r.type===$('#type').value)&&(!$('#from').value||r.date>=$('#from').value)&&(!$('#to').value||r.date<=$('#to').value)).sort((a,b)=>$('#sort').value==='az'?a.company.localeCompare(b.company,'tr'):$('#sort').value==='old'?a.date.localeCompare(b.date):b.date.localeCompare(a.date))}
function render(){const found=filtered();$('#result-count').textContent=found.length+' belge'+(found.length!==rows.length?' / '+rows.length+' belge':'')+' · '+new Set(found.map(x=>x.ticker)).size+' şirket';$('#empty').hidden=found.length>0;$('#load-more').hidden=found.length<=limit;$('#cards').innerHTML=found.slice(0,limit).map(r=>`<article class="card"><div class="card-top"><span class="ticker">${esc(r.ticker)}</span><time class="card-date" datetime="${r.date}">${date(r.date)}</time></div><div class="card-body"><h3>${esc(r.company)}</h3><p class="sector-label">${esc(r.sector)}</p><div class="badges"><span class="badge">${esc(r.type)}</span><span class="badge">${esc(r.market)}</span>${r.revision?'<span class="badge rev">Revizyon etiketli</span>':''}</div></div><div class="card-bottom"><span>PDF · ${size(r.bytes)}</span><button class="read-report" data-id="${r.id}" aria-label="${esc(r.company+' '+date(r.date)+' raporunu incele')}">Raporu incele <span aria-hidden="true">↗</span></button></div></article>`).join('');localizeDocument()}
function openDialog(d){lastFocus=document.activeElement;if(d.id==='detail'){const frame=d.querySelector('iframe');const report=rows.find(r=>frame?.getAttribute('src')?.startsWith(r.file+'#'));if(report){const a=document.createElement('a');a.href='explore/?report='+report.id;a.textContent='Bu raporu veri laboratuvarında aç ↗';a.className='data-reader-link';frame.before(a)}}localizeDocument();d.showModal()}
function detail(id){const r=rows.find(x=>x.id===id);if(!r)return;$('#detail-content').innerHTML=`<h2>${esc(r.company)}</h2><div class="detail-meta"><span class="badge">${esc(r.ticker)}</span><span class="badge">${date(r.date)}</span><span class="badge">${esc(r.type)}</span>${r.revision?'<span class="badge rev">Revizyon etiketli</span>':''}</div><p>${esc(r.sector)} · ${esc(r.market)} · ${size(r.bytes)}</p><p class="detail-warning">Tarihli arşiv belgesi. İçindeki fiyat, hedef ve görüşler raporun kendi veri kesimine aittir; güncel görüş olarak değerlendirilmemelidir.</p><div class="pdf-actions"><a href="${r.file}" target="_blank" rel="noopener">PDF’yi yeni sekmede aç ↗</a><a href="${r.file}" download="${esc(r.filename)}">Orijinal PDF’yi indir ↓</a></div><p class="filename">${esc(r.filename)}</p><iframe class="pdf-frame" title="${esc(r.company)} PDF raporu" src="${r.file}#view=FitH" loading="lazy"></iframe><h3>Bu şirketin diğer belgeleri</h3><div id="related"></div><p class="filename">SHA-256: ${r.sha256}</p>`;const related=rows.filter(x=>x.ticker===r.ticker&&x.id!==r.id);$('#related').innerHTML=related.length?related.map(x=>`<p><button class="read-report" data-related="${x.id}">${date(x.date)} · ${esc(x.type)}${x.revision?' · Revizyon etiketli':''} ↗</button></p>`).join(''):'<p>Bu katalogda başka belge yok.</p>';openDialog($('#detail'))}
$('#cards').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)detail(b.dataset.id)});
$('#detail').addEventListener('click',e=>{const b=e.target.closest('[data-related]');if(b){$('#detail').close();detail(b.dataset.related)}});
for(const id of ['search','sector','market','type','from','to','sort'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>{limit=18;render()});
$('#reset').onclick=reset;$('#empty-reset').onclick=reset;$('#load-more').onclick=()=>{limit+=18;render()};
for(const id of ['method-open','method-bottom'])$('#'+id).onclick=()=>openDialog($('#method'));
for(const d of document.querySelectorAll('dialog')){d.querySelector('.close').onclick=()=>d.close();d.addEventListener('close',()=>{if(d.id==='detail')d.querySelector('iframe')?.remove();lastFocus?.focus()});d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close()}})}
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
fetch('catalog.json').then(r=>{if(!r.ok)throw Error('Arşiv yüklenemedi');return r.json()}).then(data=>{rows=data.reports;catalogDate=data.catalogDate;$('#report-count').textContent=rows.length;$('#company-count').textContent=new Set(rows.map(r=>r.ticker)).size;$('#latest-date').textContent=date(rows[0].date);$('#catalog-date').textContent='Katalog: '+date(data.catalogDate);for(const id of ['sector','market','type'])for(const v of [...new Set(rows.map(r=>r[id]))].sort((a,b)=>a.localeCompare(b,'tr'))){const o=document.createElement('option');o.value=v;o.textContent=v;$('#'+id).append(o)}render()}).catch(()=>{$('#result-count').textContent='Arşiv yüklenemedi. Sayfayı yenileyip tekrar deneyin.'});
